import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_gelu(torch::Tensor x);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_gelu_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    int64_t total)
{
    constexpr float gelu_scale = 0.7978845608028654f;
    constexpr float gelu_coeff = 0.044715f;
    const bool aligned =
        ((reinterpret_cast<uintptr_t>(x) |
          reinterpret_cast<uintptr_t>(y)) & 15u) == 0;
    const int64_t vectors = (total + 3) / 4;
    const int64_t first =
        static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    const int64_t stride =
        static_cast<int64_t>(blockDim.x) * gridDim.x;
    for (int64_t vec_idx = first; vec_idx < vectors; vec_idx += stride) {
        const int64_t idx = vec_idx * 4;
        if (aligned && idx + 4 <= total) {
            float4 xv = reinterpret_cast<const float4*>(x)[vec_idx];
            float4 yv;
            #pragma unroll 1
            for (int i = 0; i < 4; ++i) {
                float v = reinterpret_cast<const float*>(&xv)[i];
                float v2 = v * v;
                float v3 = v2 * v;
                float inner = gelu_scale * (v + gelu_coeff * v3);
                reinterpret_cast<float*>(&yv)[i] =
                    0.5f * v * (1.0f + __tanhf(inner));
            }
            reinterpret_cast<float4*>(y)[vec_idx] = yv;
        } else {
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                const int64_t element = idx + i;
                if (element < total) {
                    float v = x[element];
                    float v2 = v * v;
                    float v3 = v2 * v;
                    float inner = gelu_scale * (v + gelu_coeff * v3);
                    y[element] = 0.5f * v * (1.0f + __tanhf(inner));
                }
            }
        }
    }
}

torch::Tensor cute_gelu(torch::Tensor x)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat,
                "x must have dtype torch.float32");

    auto xc = x.contiguous();
    auto y = torch::empty_like(xc);

    int64_t total = xc.numel();
    if (total == 0) {
        return y;
    }
    constexpr int threads = 256;
    int64_t vectors = (total + 3) / 4;
    int64_t required_blocks = (vectors + threads - 1) / threads;
    int blocks = static_cast<int>(
        required_blocks < 4096 ? required_blocks : 4096);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_gelu_kernel<<<blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(),
        y.data_ptr<float>(),
        total);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "cute_gelu_kernel launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_fused_gelu_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_gelu"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, x):
        return self._ext.cute_gelu(x)

